import{c as a,Q as e,j as d,m as i}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"Load3DBitMode","description":"","frontmatter":{},"headers":[{"level":1,"title":"Load3DBitMode","slug":"load3dbitmode"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load3DBitMode.md","filePath":"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load3DBitMode.md"}'),n={name:"api/SIMD-API/基础API/矩阵计算（ISASI）/数据搬运/LoadData/Load3DBitMode.md"};function o(r,t,s,l,p,h){return e(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="load3dbitmode" tabindex="-1">Load3DBitMode <a class="header-anchor" href="#load3dbitmode" aria-label="Permalink to &quot;Load3DBitMode&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>Load3D用于完成image to column操作，将多维feature map转为二维矩阵。支持如下数据通路：A1-&gt;A2; B1-&gt;B2。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition Dst, TPosition Src, typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void LoadData(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src,const Load3DBitModeParam&amp; loadDataParams)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>源操作数和目的操作数的数据类型。 Load3DBitMode接口： Ascend 950PR/Ascend 950DT，支持数据类型为：uint8_t/int8_t/fp8_e4m3fn_t/fp8_e5m2_t/hifloat8_t/half/bfloat16_t/uint32_t/int32_t/float</td></tr><tr><td>Src</td><td>源操作数存储的逻辑位置（TPosition），仅Load3DBitMode接口使用。</td></tr><tr><td>Dst</td><td>目的操作数存储的逻辑位置（TPosition），仅Load3DBitMode接口使用。</td></tr></tbody></table><p><strong>表 2</strong> 通用参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。 数据连续排列顺序由目的操作数所在TPosition决定，具体约束如下： A2：ZZ格式/NZ格式；B2：ZN格式；A1/B1：无格式要求，一般情况下为NZ格式。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为LocalTensor或GlobalTensor。 数据类型需要与dst保持一致。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为： Load3DBitModeParam，具体参考表3 上述结构体参数定义请参考\${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_mm.h，\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。</td></tr></tbody></table><p><strong>表 3</strong> Load3DBitModeParam类参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>config0</td><td>uint64_t类型，与Load3DBitModeConfig0位域（bit-field）结构体类型参数config0BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig0()函数获取其值。</td></tr><tr><td>config0BitMode</td><td>Load3DBitModeConfig0位域（bit-field）结构体类型，参数参考表4，与config0组成联合体（union）。</td></tr><tr><td>config1</td><td>uint64_t类型，与Load3DBitModeConfig1位域（bit-field）结构体类型参数config1BitMode组成联合体（union），初始化为0，可以使用类对象的GetConfig1()函数获取其值。</td></tr><tr><td>config1BitMode</td><td>Load3DBitModeConfig1位域（bit-field）结构体类型，参数参考表5，与config1组成联合体（union）。</td></tr></tbody></table><p>Load3DBitModeParam类参数设计思想说明：</p><p>联合体（union）是一种特殊的数据结构，允许在相同的内存位置存储不同的数据类型。union的所有成员共享同一块内存空间，大小由最大成员决定，同一时间只能使用一个成员。</p><p>位域（bit-field）是一种特殊的类成员，允许精确控制结构体中成员变量所占用的内存位数。结构体中成员变量从上到下对应内存中从低位到高位。</p><p>Load2DBitModeParam类使用union与bit-field方法，采用bit位表达参数类型，使用bit-field结构体自动处理入参的bit位数，并利用union的特性实现多参数融合传递，仅需传递一个入参即可包含全部所需信息，对应底层接口仅需要接收一个参数。同时，当需要修改参数中某一bit位的值时，仅需要通过循环和位运算即可实现，不需要重新传入参数，减少了scalar计算，实现性能提升。</p><p>Load2DBitModeParam类可以直接使用LoadData2DParamsV2结构体类型对象初始化：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline Load3DBitModeParam(const LoadData3DParamsV2&lt;T&gt; &amp;loadData3DParams_);</span></span></code></pre></div><p>也可以使用各参数的Set函数修改参数值，并且由于使用了联合体，还可以对congfig0和config1直接进行逐bit位修改来修改参数。</p><p><strong>表 4</strong> Load3DBitModeConfig0结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>kStep</td><td>该指令在目的操作数width维度的传输长度，如果不覆盖最右侧的分形，对于half类型，应为16的倍数，对于int8_t/uint8_t应为32的倍数；覆盖的情况则无倍数要求。取值范围: kStep∈[1, 65535] 。 （与表4中的kExtension含义相同） 该参数是位域结构体的最低位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetKExtension()函数设置其值，使用GetKExtension()函数获取其值。</td></tr><tr><td>mStep</td><td>该指令在目的操作数height维度的传输长度，如果不覆盖最下侧的分形，对于half/int8_t/uint8_t，应为16的倍数；覆盖的情况则无倍数要求。取值范围：mStep∈[1, 65535] 。 （与表4中的mExtension含义相同） 该参数是位域结构体的第二低位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetMExtension()函数设置其值，使用GetMExtension()函数获取其值。</td></tr><tr><td>kPos</td><td>该指令在目的操作数width维度的起点，对于half类型，应为16的倍数，对于int8_t/uint8_t应为32的倍数。取值范围[0, 65535] 。默认为0。 （与表4中的kStartPt含义相同） 该参数是位域结构体的第三低位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetKStartPt()函数设置其值，使用GetKStartPt()函数获取其值。</td></tr><tr><td>mPos</td><td>该指令在目的操作数height维度的起点，如果不覆盖最下侧的分形，对于half/int8_t/uint8_t，应为16的倍数；覆盖的情况则无倍数要求。取值范围[0, 65535] 。默认为0。 （与表4中的mStartPt含义相同） 该参数是位域结构体的最高位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetMStartPt()函数设置其值，使用GetMStartPt()函数获取其值。</td></tr></tbody></table><p><strong>表 5</strong> Load3DBitModeConfig1结构体参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>strideW</td><td>卷积核在源操作数width维度滑动的步长，取值范围：strideW∈[1, 63] 。 （与表4中的strideW含义相同） 该参数是位域结构体的最低位参数，占用6bit，可以使用Load3DBitModeParam类对象的SetStrideW()函数设置其值，使用GetStrideW()函数获取其值。</td></tr><tr><td>strideH</td><td>卷积核在源操作数height 维度滑动的步长，取值范围：strideH∈[1, 63] 。 （与表4中的strideH含义相同） 该参数是位域结构体的第二低位参数，占用6bit，可以使用Load3DBitModeParam类对象的SetStrideH()函数设置其值，使用GetStrideH()函数获取其值。</td></tr><tr><td>Wk</td><td>卷积核width，取值范围：Wk∈[1, 255] 。 （与表4中的filterW含义相同） 该参数是位域结构体的第三低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetFilterW()函数设置其值，使用GetFilterW()函数获取其值。</td></tr><tr><td>Hk</td><td>卷积核height，取值范围：Hk∈[1, 255] 。 （与表4中的filterH含义相同） 该参数是位域结构体的第四低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetFilterH()函数设置其值，使用GetFilterH()函数获取其值。</td></tr><tr><td>dilationW</td><td>卷积核width膨胀系数，取值范围：dilationW∈[1, 255] 。 （与表4中的dilationFilterW含义相同） 该参数是位域结构体的第五低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetDilationFilterW()函数设置其值，使用GetDilationFilterW()函数获取其值。</td></tr><tr><td>dilationH</td><td>卷积核height膨胀系数，取值范围：dilationH∈[1, 255]。 （与表4中的dilationFilterH含义相同） 该参数是位域结构体的第六低位参数，占用8bit，可以使用Load3DBitModeParam类对象的SetDilationFilterH()函数设置其值，使用GetDilationFilterH()函数获取其值。</td></tr><tr><td>filterW</td><td>是否在filterW的基础上将卷积核width增加256 个元素。true，增加；false，不增加。 （与表4中的filterSizeW含义相同） 该参数是位域结构体的第七低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetFilterSizeW()函数设置其值，使用GetFilterSizeW()函数获取其值。</td></tr><tr><td>filterH</td><td>是否在filterH的基础上将卷积核height增加256个元素。true，增加；false，不增加。 （与表4中的filterSizeH含义相同） 该参数是位域结构体的第八低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetFilterSizeH()函数设置其值，使用GetFilterSizeH()函数获取其值。</td></tr><tr><td>transpose</td><td>是否启用转置功能，对整个目标矩阵进行转置，支持数据类型为 bool，仅在目的TPosition为A2，且源操作数为half类型时有效。默认为false。 true：启用false：不启用 （与表4中的enTranspose含义相同） 该参数是位域结构体的第九低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetTranspose()函数设置其值，使用GetTranspose()函数获取其值。</td></tr><tr><td>fmatrixCtrl</td><td>表示LoadData3DV2指令从左矩阵还是右矩阵获取FeatureMap的属性描述，与SetFmatrix配合使用，当前只支持设置为false，默认值为false。 true：从右矩阵中获取FeatureMap的属性描述；false：从左矩阵中获取FeatureMap的属性描述。 （与表4中的fMatrixCtrl含义相同） 该参数是位域结构体的第十低位参数，占用1bit，可以使用Load3DBitModeParam类对象的SetFmatrixCtrl()函数设置其值，使用GetFmatrixCtrl()函数获取其值。</td></tr><tr><td>sizeChannel</td><td>源操作数的通道数，取值范围：channelSize∈[1, 63] 。 channelSize的取值要求为：对于uint32_t/int32_t/float，channelSize可取值为4，N * 8，N * 8 + 4；对于half/bfloat16，channelSize可取值为4，8，N * 16，N * 16 + 4，N * 16 + 8；对于int8_t/uint8_t，channelSize可取值为4，8，16， 32 * N，N * 32 + 4，N * 32 + 8，N * 32 + 16；对于int4b_t，ChannelSize可取值为8，16，32，N * 64，N * 64 + 8，N * 64 + 16，N * 64 + 32。N为正整数。 （与表4中的channelSize含义相同） 该参数是位域结构体的最高位参数，占用16bit，可以使用Load3DBitModeParam类对象的SetChannelSize()函数设置其值，使用GetChannelSize()函数获取其值。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>该调用示例支持的运行平台为Atlas 推理系列产品AI Core。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint16_t C1 = 2;</span></span>
<span class="line"><span>uint16_t H = 4, W = 4;</span></span>
<span class="line"><span>uint8_t Kh = 2, Kw = 2;</span></span>
<span class="line"><span>uint16_t Cout = 16;</span></span>
<span class="line"><span>uint16_t C0 = 16;</span></span>
<span class="line"><span>uint8_t dilationH = 2, dilationW = 2;</span></span>
<span class="line"><span>uint8_t padTop = 1, padBottom = 1, padLeft = 1, padRight = 1;</span></span>
<span class="line"><span>uint8_t strideH = 1, strideW = 1;</span></span>
<span class="line"><span>uint8_t padList[4] = {padLeft, padRight, padTop, padBottom};</span></span>
<span class="line"><span>LoadData3DParamsV2 param = { padList, H, W, 0, 0, 0, -1, -1, strideW, strideH, Kw, Kh, dilationW, dilationH, 1, 0, fmRepeat, 0, (half)(0)};</span></span>
<span class="line"><span>Load3DBitModeParam paramBitMode(param);  </span></span>
<span class="line"><span>AscendC::LoadData&lt;A2, A1, half&gt;(featureMapA2, featureMapA1, paramBitMode);</span></span>
<span class="line"><span>AscendC::LoadData(weightB2, weightB1, { 0, weRepeat, 1, 0, 0, false, 0 });</span></span></code></pre></div>`,32)])])}const m=a(n,[["render",o]]);export{b as __pageData,m as default};
